def _extract_ts_vals(series):
    if series is None:
        return ([], [])
    ts = [t for t, v in series]
    vals = [float(v) for t, v in series]
    return (ts, vals)

def _find_episodes(spo2_series, threshold, min_consec=2):
    if not spo2_series:
        return []
    episodes = []
    in_run = False
    run_start_idx = None
    run_len = 0
    for i, (t, v) in enumerate(spo2_series):
        below = v < threshold
        if below:
            if not in_run:
                in_run = True
                run_start_idx = i
                run_len = 1
            else:
                run_len += 1
        elif in_run:
            if run_len >= min_consec:
                sidx = run_start_idx
                eidx = i - 1
                episodes.append({'threshold': threshold, 'start_time': spo2_series[sidx][0], 'end_time': spo2_series[eidx][0], 'start_idx': sidx, 'end_idx': eidx, 'n_readings': run_len, 'min_spo2': float(min((vv for _, vv in spo2_series[sidx:eidx + 1])))})
            in_run = False
            run_start_idx = None
            run_len = 0
    if in_run and run_len >= min_consec:
        sidx = run_start_idx
        eidx = len(spo2_series) - 1
        episodes.append({'threshold': threshold, 'start_time': spo2_series[sidx][0], 'end_time': spo2_series[eidx][0], 'start_idx': sidx, 'end_idx': eidx, 'n_readings': run_len, 'min_spo2': float(min((vv for _, vv in spo2_series[sidx:eidx + 1])))})
    return episodes

def _subset_by_window(series, t_start, t_end):
    if not series:
        return ([], [])
    ts = []
    vals = []
    for t, v in series:
        if t_start <= t <= t_end:
            ts.append(t)
            vals.append(float(v))
    return (ts, vals)
