    window_end = t1 + np.timedelta64(int(pad_minutes * 60), 's') if hasattr(t1, 'astype') else t1 + (t1 - t1) + (t1 - t1)
    try:
        from datetime import timedelta
        window_start = t0 - timedelta(minutes=pad_minutes)
        window_end = t1 + timedelta(minutes=pad_minutes)
    except Exception:
        window_start = t0
        window_end = t1
